import type { AccordionSectionProps } from "../accordion.types";

import { forwardRef, useCallback, useMemo } from "react";
import { clsx } from "clsx";
import { useUniqueId } from "@system";

import { useAccordion } from "../hooks/use-accordion";
import { AccordionClasses } from "../accordion.styles";
import { AccordionSectionContext } from "../hooks/use-accordion-section";

export const AccordionSection = forwardRef<HTMLDivElement, AccordionSectionProps>(
  (
    {
      children,
      isInitialOpen = false,
      className,
      onValueChange,
      isExpanded: controlledExpanded,
      ...props
    },
    ref,
  ) => {
    const { openIndex, setOpenIndex, onePanelAtATime, registerSection } = useAccordion();
    const sectionClasses = clsx(AccordionClasses.section, className);

    // eslint-disable-next-line react-hooks/exhaustive-deps
    const sectionIndex = useMemo(() => registerSection(isInitialOpen), [isInitialOpen]);

    const sectionId = useUniqueId("accordion-section");
    const buttonId = useUniqueId("accordion-section-button");

    const isExpanded = useMemo(() => {
      return (controlledExpanded || openIndex?.includes(sectionIndex)) ?? false;
    }, [openIndex, sectionIndex, controlledExpanded]);

    const handleToggle = useCallback(() => {
      setOpenIndex((prevOpenIndex) => {
        const currentOpenIndexes = prevOpenIndex ?? [];
        const isOpen = currentOpenIndexes.includes(sectionIndex);
        onValueChange?.(isOpen);

        if (onePanelAtATime) {
          return isOpen ? null : [sectionIndex];
        } else {
          return isOpen
            ? currentOpenIndexes.filter((i) => i !== sectionIndex)
            : [...currentOpenIndexes, sectionIndex];
        }
      });
    }, [setOpenIndex, sectionIndex, onePanelAtATime, onValueChange]);

    const contextValue = useMemo(
      () => ({
        isExpanded,
        sectionId,
        buttonId,
        handleToggle,
        sectionIndex,
      }),
      [isExpanded, sectionId, buttonId, handleToggle, sectionIndex],
    );

    return (
      <AccordionSectionContext.Provider value={contextValue}>
        <div ref={ref} className={sectionClasses} data-expanded={isExpanded} {...props}>
          {children}
        </div>
      </AccordionSectionContext.Provider>
    );
  },
);

AccordionSection.displayName = "Accordion.Section";
